const PROFILES={sand:[360,.035,57,.018],light:[1800,.012,98,.025],machine:[600,.045,60,.055],water:[1050,.055,43,.013],storm:[750,.065,38,.03]};
export class Atmosphere {
  constructor(){this.enabled=false;this.context=null;this.motif='sand';this.weather='none';this.sources=[];this.revision=0;}
  init(){const Audio=globalThis.AudioContext||globalThis.webkitAudioContext;if(!Audio)return false;const ctx=this.context=new Audio();this.master=ctx.createGain();this.master.gain.value=.2;this.master.connect(ctx.destination);this.filter=ctx.createBiquadFilter();this.filter.type='lowpass';this.noiseGain=ctx.createGain();this.humGain=ctx.createGain();this.filter.connect(this.noiseGain).connect(this.master);this.humGain.connect(this.master);const b=ctx.createBuffer(2,ctx.sampleRate*6,ctx.sampleRate);for(let ch=0;ch<2;ch++){const data=b.getChannelData(ch);for(let i=0;i<data.length;i++)data[i]=Math.random()*2-1;}const noise=ctx.createBufferSource();noise.buffer=b;noise.loop=true;noise.connect(this.filter);this.osc=ctx.createOscillator();this.osc.type='sine';this.osc.connect(this.humGain);this.sources=[noise,this.osc];this.setScene(this.motif,this.weather);this.sources.forEach(n=>n.start());return true;}
  async toggle(){const revision=++this.revision;this.enabled=!this.enabled;try{if(this.enabled&&!this.context&&!this.init())this.enabled=false;if(this.context)await(this.enabled&&!document.hidden?this.context.resume():this.context.suspend());if(revision!==this.revision)return this.enabled;return this.enabled;}catch{this.enabled=false;return false;}}
  pause(){this.revision++;this.enabled=false;this.context?.suspend().catch(()=>{});}
  setScene(motif,weather='none'){this.motif=motif;this.weather=weather;if(!this.context)return;const[c,n,f,h]=PROFILES[motif]||PROFILES.sand;const t=this.context.currentTime;for(const[param,value]of[[this.filter.frequency,c],[this.noiseGain.gain,n*(weather==='none'?1:1.25)],[this.osc.frequency,f],[this.humGain.gain,h]]){param.cancelScheduledValues(t);param.setTargetAtTime(value,t,.7);}}
  cue(kind){const ctx=this.context;if(!this.enabled||document.hidden||ctx?.state!=='running')return;const o=ctx.createOscillator(),g=ctx.createGain(),now=ctx.currentTime;o.frequency.value=({inspect:640,deduction:440,choice:330,ending:220})[kind]||520;g.gain.setValueAtTime(0,now);g.gain.linearRampToValueAtTime(.03,now+.02);g.gain.exponentialRampToValueAtTime(.0001,now+.24);o.connect(g).connect(this.master);o.onended=()=>{o.disconnect();g.disconnect();};o.start();o.stop(now+.26);}
}
